import{_ as o,r as s,o as p,c,e,a as r,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"介绍 - October CMS - 3.x","titleTemplate":false,"description":"使用 Tailor 将网站内容定制为您的精确需求。","frontmatter":{"subtitle":"使用 Tailor 将网站内容定制为您的精确需求。"},"headers":[{"level":2,"title":"目录结构","slug":"目录结构","link":"#目录结构","children":[{"level":3,"title":"应用蓝图","slug":"应用蓝图","link":"#应用蓝图","children":[]},{"level":3,"title":"主题蓝图","slug":"主题蓝图","link":"#主题蓝图","children":[]}]},{"level":2,"title":"蓝图类型","slug":"蓝图类型","link":"#蓝图类型","children":[]},{"level":2,"title":"蓝图结构","slug":"蓝图结构","link":"#蓝图结构","children":[]},{"level":2,"title":"与多站点集成","slug":"与多站点集成","link":"#与多站点集成","children":[]},{"level":2,"title":"迁移蓝图","slug":"迁移蓝图","link":"#迁移蓝图","children":[{"level":3,"title":"刷新内容","slug":"刷新内容","link":"#刷新内容","children":[]},{"level":3,"title":"传播内容","slug":"传播内容","link":"#传播内容","children":[]},{"level":3,"title":"清理内容","slug":"清理内容","link":"#清理内容","children":[]}]}],"relativePath":"3.x/zh-cn/cms/tailor/introduction.md","filePath":"3.x/zh-cn/cms/tailor/introduction.md"}'),d={name:"3.x/zh-cn/cms/tailor/introduction.md"};function u(h,a,g,k,m,b){const n=s("pre-heading"),t=s("post-heading"),l=s("VideoBlockLink");return p(),c("div",null,[e(n),a[0]||(a[0]=r("h1",null,"介绍",-1)),e(t),e(l,{src:"https://www.youtube.com/watch?v=_WMH4mlMdjk",title:"Tailor Tutorial",description:"本视频介绍如何使用 Tailor 快速创建完整的博客解决方案。",prompt:"观看教程"}),a[1]||(a[1]=i(`<p>Tailor 是一项功能，用于定义网站使用的基于文件的内容结构，例如公司博客或团队页面。Tailor 自动生成用于管理记录的后端用户界面，并提供 CMS 组件用于在前端显示和链接记录。</p><p>使用 Tailor 时，您可以跳过传统的插件开发工作流程，直接定义内容。字段通过蓝图模板简单定义，内容存储在特殊的数据库表中。蓝图模板还可以指定导航和其他修饰符。</p><h2 id="目录结构"><a href="#目录结构" class="header-anchor">#</a> 目录结构</h2><p>蓝图是 YAML 文件，默认位于 <strong>app/blueprints</strong> 目录中，此外还有 <strong>themes/.../blueprints</strong> 目录用于 <a href="./../themes/themes.html">CMS 主题</a>。蓝图的放置位置取决于使用场景：<strong>应用蓝图</strong> 全局可用，而 <strong>主题蓝图</strong> 仅在选择该主题时可用。</p><h3 id="应用蓝图"><a href="#应用蓝图" class="header-anchor">#</a> 应用蓝图</h3><p>下面是一个蓝图目录结构示例。每个蓝图可以位于任何目录中，并且可以使用任何文件名。蓝图可以组织在任意嵌套深度的子目录中。</p><pre class="dir-container"><code><p>├── app
|   └── <code>blueprints</code>  <em>← 蓝图从这里开始</em>
|       ├── blog
|       │   └── blog.yaml
|       │   └── author.yaml
|       ├── about
|       │   └── about.yaml
|       ├── wiki
|       │   └── article.yaml</p>
</code></pre><h3 id="主题蓝图"><a href="#主题蓝图" class="header-anchor">#</a> 主题蓝图</h3><p>接下来是 <strong>demo</strong> 主题中蓝图结构的示例。与应用目录中一样，蓝图可以位于任何目录中，使用任何文件名，具有任意嵌套深度。这些蓝图的管理面板导航仅在选择该主题时出现，通常由<a href="./../resources/multisite.html">多站点设置</a>控制。</p><pre class="dir-container"><code><p>├── themes
|   └── demo
|       ├── <code>blueprints</code>  <em>← 蓝图从这里开始</em>
|       │   └── settings.yaml
|       │   └── color-scheme.yaml</p>
</code></pre><h2 id="蓝图类型"><a href="#蓝图类型" class="header-anchor">#</a> 蓝图类型</h2><p>蓝图的 <strong>type</strong> 属性决定蓝图的实现方式。有多种类型可用，大多数蓝图会指定<a href="./../../element/form-fields.html">表单字段定义</a>。</p><div class="table"><table tabindex="0"><thead><tr><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>Entry</td><td>支持草稿的标准内容结构。</td></tr><tr><td>Global</td><td>数据库中的单条记录，通常用于设置和配置。</td></tr><tr><td>Mixin</td><td>定义可重用的字段定义，可以导入并与其他字段定义混合使用。</td></tr></tbody></table></div><p>每种蓝图类型在<a href="./blueprints.html">蓝图文章</a>中有更详细的描述。</p><h2 id="蓝图结构"><a href="#蓝图结构" class="header-anchor">#</a> 蓝图结构</h2><div class="custom-block aside"><p>蓝图 100% 可移植。它们使用内部标识符，可以位于任何目录中，使用任何文件名。</p></div><p>蓝图使用 YAML 语法定义，始终包含三个标识符：唯一的 UUID、用户友好的 handle 和蓝图类型。蓝图的文件名和文件夹用于组织蓝图，不作为标识符使用。所有其他属性在蓝图的相关文档文章中定义。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">uuid</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
<span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Post

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token comment"># [...]</span>
</code></pre></div><p>蓝图 <strong>handle</strong> 是一种人类可读的方式来引用蓝图对象。以上面的蓝图为例，我们可以使用 handle 来引用条目。</p><div class="custom-block tip"><p>Handle 遵循与 PHP 命名空间类似的命名约定，可以使用反斜杠 <code>\\</code> 分隔符进行组织。</p></div><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><p>蓝图 <strong>uuid</strong> 是蓝图之间相互引用时使用的唯一标识符。例如，当字段引用混入时。首次创建蓝图时，您可以选择不包含 UUID，系统会在首次迁移时自动为您创建一个。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">_blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">source</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
</code></pre></div><h2 id="与多站点集成"><a href="#与多站点集成" class="header-anchor">#</a> 与多站点集成</h2><p>蓝图默认不使用<a href="./../resources/multisite.html">多站点功能</a>。您可以使用 <code>multisite</code> 属性来启用此功能。启用后，记录可以在每个配置的站点中保持唯一。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>启用多站点后，蓝图中的所有字段都变为可翻译的。要保持某个字段的值不变，请将 <code>translatable</code> 属性设置为 false。在此示例中，保存记录时 <strong>name</strong> 字段将被复制到每个站点。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
        <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>您还可以将值设置为 <strong>sync</strong> 以保持记录在各站点之间同步，这对于分类和标签很有用。使用 sync 时，每条记录将始终存在于每个站点上，尽管内容可以不同。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> sync
</code></pre></div><p>使用<a href="./../resources/multisite.html">站点组</a>时，记录将传播到该组内的所有站点。可以通过将 <code>multisite</code> 属性设置为 <strong>all</strong> 来更改此行为，以在所有站点之间同步。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> all
</code></pre></div><p>设置为 <strong>locale</strong> 将把记录同步到共享相同区域设置的所有站点。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> locale
</code></pre></div><h2 id="迁移蓝图"><a href="#迁移蓝图" class="header-anchor">#</a> 迁移蓝图</h2><p>蓝图及其结构在正常的数据库迁移过程中进行迁移。当手动更改蓝图文件时，您应该运行 <code>tailor:migrate</code> 命令来更新数据库表。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:migrate
</code></pre></div><div class="custom-block tip"><p>当调试模式关闭时，蓝图会被缓存。迁移命令也可以用于清除蓝图缓存。</p></div><h3 id="刷新内容"><a href="#刷新内容" class="header-anchor">#</a> 刷新内容</h3><p>您可以使用 <code>tailor:refresh</code> 命令删除 Tailor 管理的所有内容。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh
</code></pre></div><p>要刷新单个蓝图，请使用 <code>--blueprint</code> 选项并指定其 handle。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div><h3 id="传播内容"><a href="#传播内容" class="header-anchor">#</a> 传播内容</h3><p>使用多站点的 <strong>sync</strong> 选项时，您可以使用 <code>tailor:propagate</code> 命令追溯传播记录。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate
</code></pre></div><p>要传播单个蓝图，请使用 <code>--blueprint</code> 选项并指定其 handle。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Category&quot;</span>
</code></pre></div><h3 id="清理内容"><a href="#清理内容" class="header-anchor">#</a> 清理内容</h3><p>作为一般规则，Tailor 永远不会删除表列和内容。如果字段被移除，列将被重命名而不是删除。例如，名为 <code>content</code> 的旧字段可能在数据库表中显示为 <code>x_content_fb418fac</code>。旧蓝图的表也会保留，以防将来恢复。</p><p>您可以使用 <code>tailor:prune</code> 命令清理未使用的数据库列。此命令还将删除不再有关联蓝图的表。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune
</code></pre></div><p>您可以仅使用 <code>--fields</code> 修饰符来清理字段。要仅清理表，请使用 <code>--tables</code> 修饰符。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--fields</span>
php artisan tailor:prune <span class="token parameter variable">--tables</span>
</code></pre></div><p>要清理单个蓝图，请使用 <code>--blueprint</code> 选项并指定其 handle。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div>`,56))])}const f=o(d,[["render",u]]);export{y as __pageData,f as default};
